create table if not exists public.recipes (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  category text not null check (category in ('сніданок', 'обід', 'вечеря', 'перекус')),
  recipe text not null default '',
  ingredients jsonb not null default '[]'::jsonb,
  calories int not null,
  protein_g numeric(6, 1) not null,
  fat_g numeric(6, 1) not null,
  carbs_g numeric(6, 1) not null
);

alter table public.recipes enable row level security;

drop policy if exists "recipes: read for signed-in users" on public.recipes;
create policy "recipes: read for signed-in users" on public.recipes
  for select to authenticated using (true);

-- Values are approximate, per serving.
on conflict (name) do nothing;
