insert into public.recipes (name, category, recipe, ingredients, calories, protein_g, fat_g, carbs_g) values
  ('Вівсянка з бананом', 'сніданок', 'Зваріть пластівці в молоці 5 хвилин. Додайте нарізаний банан і мед.', '[{"name": "Вівсяні пластівці", "amount": "50 г"}, {"name": "Молоко", "amount": "150 мл"}, {"name": "Банан", "amount": "1 шт"}, {"name": "Мед", "amount": "1 ч. л."}]'::jsonb, 320, 9, 6, 58),
  ('Омлет з овочами', 'сніданок', 'Обсмажте нарізані овочі 3 хвилини. Залийте збитими яйцями й тримайте під кришкою 5 хвилин.', '[{"name": "Яйця", "amount": "3 шт"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Солодкий перець", "amount": "0.5 шт"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 280, 19, 20, 5),
  ('Сирники', 'сніданок', 'Змішайте інгредієнти, сформуйте сирники й смажте по 3 хвилини з кожного боку.', '[{"name": "Сир кисломолочний", "amount": "200 г"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Борошно", "amount": "2 ст. л."}, {"name": "Цукор", "amount": "1 ст. л."}]'::jsonb, 340, 24, 12, 33),
  ('Гречана каша з молоком', 'сніданок', 'Відваріть гречку до готовності, залийте гарячим молоком і додайте масло.', '[{"name": "Гречка", "amount": "60 г"}, {"name": "Молоко", "amount": "200 мл"}, {"name": "Вершкове масло", "amount": "5 г"}]'::jsonb, 300, 11, 7, 49),
  ('Тост з авокадо та яйцем', 'сніданок', 'Підсушіть хліб, намажте розім''ятим авокадо з лимонним соком, зверху покладіть зварене яйце.', '[{"name": "Цільнозерновий хліб", "amount": "2 скибки"}, {"name": "Авокадо", "amount": "0.5 шт"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Лимонний сік", "amount": "1 ч. л."}]'::jsonb, 360, 14, 22, 26),
  ('Грецький йогурт з ягодами', 'сніданок', 'Викладіть йогурт у миску, додайте ягоди та гранолу.', '[{"name": "Грецький йогурт", "amount": "200 г"}, {"name": "Ягоди", "amount": "100 г"}, {"name": "Гранола", "amount": "30 г"}]'::jsonb, 290, 17, 8, 37),
  ('Рисова каша з яблуком', 'сніданок', 'Зваріть рис у молоці до густоти, додайте терте яблуко та корицю.', '[{"name": "Рис", "amount": "50 г"}, {"name": "Молоко", "amount": "200 мл"}, {"name": "Яблуко", "amount": "1 шт"}, {"name": "Кориця", "amount": "щіпка"}]'::jsonb, 310, 7, 6, 58),
  ('Борщ', 'обід', 'Зваріть бульйон з яловичини. Додайте картоплю, капусту, засмажку з буряка, моркви й томатної пасти. Варіть 20 хвилин.', '[{"name": "Буряк", "amount": "1 шт"}, {"name": "Капуста", "amount": "150 г"}, {"name": "Картопля", "amount": "2 шт"}, {"name": "Морква", "amount": "1 шт"}, {"name": "Яловичина", "amount": "100 г"}, {"name": "Томатна паста", "amount": "1 ст. л."}]'::jsonb, 250, 9, 10, 30),
  ('Курячий суп з локшиною', 'обід', 'Зваріть бульйон з курки, додайте картоплю, моркву, цибулю. За 5 хвилин до кінця всипте локшину.', '[{"name": "Куряче філе", "amount": "100 г"}, {"name": "Локшина", "amount": "40 г"}, {"name": "Картопля", "amount": "1 шт"}, {"name": "Морква", "amount": "1 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}]'::jsonb, 220, 16, 6, 24),
  ('Гречка з курячим філе', 'обід', 'Відваріть гречку. Обсмажте нарізане філе з цибулею до золотистого кольору й подавайте разом.', '[{"name": "Гречка", "amount": "80 г"}, {"name": "Куряче філе", "amount": "150 г"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 480, 40, 9, 59),
  ('Плов з куркою', 'обід', 'Обсмажте м''ясо, додайте цибулю й моркву, потім рис і воду. Тушкуйте під кришкою 25 хвилин.', '[{"name": "Рис", "amount": "80 г"}, {"name": "Куряче стегно без шкіри", "amount": "150 г"}, {"name": "Морква", "amount": "1 шт"}, {"name": "Цибуля", "amount": "1 шт"}, {"name": "Олія", "amount": "1 ст. л."}, {"name": "Часник", "amount": "2 зубчики"}]'::jsonb, 520, 30, 18, 62),
  ('Крем-суп з гарбуза', 'обід', 'Відваріть гарбуз із цибулею, збийте блендером, додайте вершки.', '[{"name": "Гарбуз", "amount": "250 г"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Вершки 10%", "amount": "50 мл"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 190, 5, 8, 25),
  ('Макарони з томатним соусом', 'обід', 'Відваріть макарони. Прогрійте томати з часником 7 хвилин, змішайте з макаронами, посипте сиром.', '[{"name": "Макарони", "amount": "80 г"}, {"name": "Томати в соку", "amount": "150 г"}, {"name": "Часник", "amount": "1 зубчик"}, {"name": "Твердий сир", "amount": "20 г"}]'::jsonb, 450, 16, 12, 69),
  ('Салат Цезар з куркою', 'обід', 'Обсмажте або запечіть філе, нарізайте. Змішайте з листям салату, соусом, сухариками й пармезаном.', '[{"name": "Куряче філе", "amount": "120 г"}, {"name": "Салат романо", "amount": "80 г"}, {"name": "Сухарики", "amount": "20 г"}, {"name": "Пармезан", "amount": "20 г"}, {"name": "Соус Цезар", "amount": "30 г"}]'::jsonb, 410, 32, 24, 15),
  ('Тушкована капуста зі свининою', 'обід', 'Обсмажте м''ясо з морквою, додайте нашатковану капусту та томатну пасту, тушкуйте 30 хвилин.', '[{"name": "Капуста", "amount": "250 г"}, {"name": "Пісна свинина", "amount": "100 г"}, {"name": "Морква", "amount": "1 шт"}, {"name": "Томатна паста", "amount": "1 ст. л."}]'::jsonb, 400, 22, 24, 24),
  ('Запечена риба з овочами', 'вечеря', 'Викладіть рибу й овочі на деко, збризніть олією та лимонним соком. Запікайте 20 хвилин при 190 °C.', '[{"name": "Філе білої риби", "amount": "180 г"}, {"name": "Кабачок", "amount": "100 г"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Лимон", "amount": "0.25 шт"}]'::jsonb, 340, 32, 16, 14),
  ('Парові курячі котлети з броколі', 'вечеря', 'Сформуйте котлети з фаршу, яйця й цибулі. Готуйте на пару 20 хвилин, броколі додайте на останні 7.', '[{"name": "Курячий фарш", "amount": "150 г"}, {"name": "Броколі", "amount": "150 г"}, {"name": "Яйце", "amount": "0.5 шт"}, {"name": "Цибуля", "amount": "0.25 шт"}]'::jsonb, 330, 34, 14, 12),
  ('Овочеве рагу', 'вечеря', 'Нарізані овочі обсмажте 5 хвилин і тушкуйте під кришкою 20 хвилин.', '[{"name": "Кабачок", "amount": "150 г"}, {"name": "Баклажан", "amount": "100 г"}, {"name": "Картопля", "amount": "1 шт"}, {"name": "Помідор", "amount": "1 шт"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Олія", "amount": "1 ч. л."}]'::jsonb, 210, 6, 8, 29),
  ('Печена картопля з індичкою', 'вечеря', 'Запікайте нарізану картоплю та філе зі спеціями 35 хвилин при 200 °C.', '[{"name": "Картопля", "amount": "250 г"}, {"name": "Філе індички", "amount": "150 г"}, {"name": "Олія", "amount": "1 ч. л."}, {"name": "Паприка", "amount": "щіпка"}]'::jsonb, 430, 33, 10, 52),
  ('Фаршировані перці', 'вечеря', 'Наповніть перці сумішшю фаршу з відвареним рисом. Тушкуйте в томатному соусі 35 хвилин.', '[{"name": "Солодкий перець", "amount": "2 шт"}, {"name": "Фарш курячий", "amount": "100 г"}, {"name": "Рис", "amount": "40 г"}, {"name": "Томатний соус", "amount": "80 г"}]'::jsonb, 360, 22, 14, 36),
  ('Лобіо з червоної квасолі', 'вечеря', 'Відваріть квасолю, змішайте з обсмаженою цибулею, часником і подрібненими горіхами. Прогрійте 10 хвилин.', '[{"name": "Червона квасоля", "amount": "100 г"}, {"name": "Цибуля", "amount": "0.5 шт"}, {"name": "Часник", "amount": "2 зубчики"}, {"name": "Волоські горіхи", "amount": "15 г"}, {"name": "Кінза", "amount": "пучок"}]'::jsonb, 300, 15, 7, 45),
  ('Салат з тунцем та яйцем', 'вечеря', 'Змішайте нарізані інгредієнти й заправте олією.', '[{"name": "Тунець консервований", "amount": "100 г"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Огірок", "amount": "1 шт"}, {"name": "Листя салату", "amount": "60 г"}, {"name": "Оливкова олія", "amount": "1 ч. л."}]'::jsonb, 310, 28, 18, 8),
  ('Деруни', 'вечеря', 'Натріть картоплю з цибулею, додайте яйце й борошно. Смажте оладки по 3 хвилини з кожного боку.', '[{"name": "Картопля", "amount": "300 г"}, {"name": "Цибуля", "amount": "0.25 шт"}, {"name": "Яйце", "amount": "1 шт"}, {"name": "Борошно", "amount": "1 ст. л."}, {"name": "Олія", "amount": "1 ст. л."}]'::jsonb, 380, 8, 18, 46),
  ('Яблуко з арахісовою пастою', 'перекус', 'Наріжте яблуко скибочками й подавайте з арахісовою пастою.', '[{"name": "Яблуко", "amount": "1 шт"}, {"name": "Арахісова паста", "amount": "1 ст. л."}]'::jsonb, 220, 6, 12, 25),
  ('Сир кисломолочний з медом', 'перекус', 'Змішайте сир із медом.', '[{"name": "Сир кисломолочний", "amount": "150 г"}, {"name": "Мед", "amount": "1 ч. л."}]'::jsonb, 190, 24, 4, 14),
  ('Хумус з морквою', 'перекус', 'Наріжте моркву паличками й подавайте з хумусом.', '[{"name": "Хумус", "amount": "50 г"}, {"name": "Морква", "amount": "2 шт"}]'::jsonb, 200, 7, 11, 19),
  ('Смузі з бананом і шпинатом', 'перекус', 'Збийте всі інгредієнти блендером.', '[{"name": "Банан", "amount": "1 шт"}, {"name": "Шпинат", "amount": "40 г"}, {"name": "Молоко", "amount": "150 мл"}]'::jsonb, 180, 5, 3, 36),
  ('Горіхи з сухофруктами', 'перекус', 'Змішайте горіхи із сухофруктами.', '[{"name": "Мигдаль", "amount": "20 г"}, {"name": "Курага", "amount": "30 г"}, {"name": "Родзинки", "amount": "10 г"}]'::jsonb, 250, 6, 16, 22),
  ('Запечені яблука з корицею', 'перекус', 'Видаліть серцевину, посипте корицею, додайте мед. Запікайте 20 хвилин при 180 °C.', '[{"name": "Яблука", "amount": "2 шт"}, {"name": "Кориця", "amount": "щіпка"}, {"name": "Мед", "amount": "1 ч. л."}]'::jsonb, 150, 1, 2, 34)
